from taf.hw.internal.device.device import AvailableDevices
from taf.hw.vertex.devices.vertex import Vertex
from taf.hw.vertex.devices.vertex_vce6 import VertexVCE6


class AvailableVertexChannelEmulatorDevices(AvailableDevices):
    """
    Map the channel emulator with vendor&model&version.
    """
    _SUPPORTED_EMULATOR = [VertexVCE6]
    _default_devices = {'default': Vertex, 'vce6': VertexVCE6}

    def _get_available_devices(self):
        return self._SUPPORTED_EMULATOR

    def find_default_device(self, model=None):
        if model:
            return self._default_devices[str(model).lower()]
        else:
            return self._default_devices['default']
